import binascii, re
h = ""
d = bytes.fromhex(h)
print("len:", len(d), "first12:", d[:12].hex())
# find tail magic
print("tail:", d[-8:].hex(), "ascii:", d[-8:].decode('latin1'))
# try: head 3 bytes then ascii header lines
print("head:", d[:3].hex(), "bytes:", list(d[:3]))
print("ascii after head:", d[3:60])
# locate \r\n\r\n ending of headers
idx = d.find(b'\r\n\r\n')
print("header end at:", idx, "headers:")
print(d[3:idx+2].decode('latin1'))
body = d[idx+4:]
print("body len:", len(body), "body tail:", body[-6:])
# frame total assuming tail 2 bytes
print("tail bytes:", d[-2:].hex())
